import * as React from "react"

import { cn } from "@/lib/utils"

export interface InputProps
  extends React.InputHTMLAttributes<HTMLInputElement> {}

const Input = React.forwardRef<HTMLInputElement, InputProps>(
  ({ className, type, ...props }, ref) => {
    return (
      <input
        type={type}
        className={cn(
          "flex h-10 w-full rounded-md border border-nomos-border bg-nomos-background px-3 py-2 text-base text-nomos-foreground ring-offset-nomos-background file:border-0 file:bg-transparent file:text-sm file:font-medium file:text-nomos-foreground placeholder:text-nomos-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-nomos-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 md:text-sm",
          className
        )}
        ref={ref}
        {...props}
      />
    )
  }
)
Input.displayName = "Input"

export { Input }
